public boolean avaParmIsWorkTemplateBreakingWorkLines(boolean _avaIsWorkTemplateBreakingWorkLines = avaIsWorkTemplateBreakingWorkLines)
{
    avaIsWorkTemplateBreakingWorkLines = _avaIsWorkTemplateBreakingWorkLines;

    return avaIsWorkTemplateBreakingWorkLines;
}

/// <summary>
/// Creates cycle count work over location.
/// </summary>
/// <param name="_location">
/// Location that cycle count work will be created for.
/// </param>
/// <param name="_itemAndDimensionsForWorkCreationSet">
/// Set of item IDs and related dimensions for which the work lines should be created; optional.
/// </param>
/// <returns>
/// true if the cycle count work is created; otherwise false.
/// </returns>
/// <remarks>
/// If there is an already existing cycle count work on the location, it is short-circuited.
/// </remarks>
public boolean avaCreateWork(WMSLocation _location, Set _itemAndDimensionsForWorkCreationSet = null)
{
    DictClass   dictClass_WhsCycleCountCreatePlan;

    dictClass_WhsCycleCountCreatePlan   = new DictClass(classNum(WhsCycleCountCreatePlan));

    if (WHSWorkLine::avaAnyCycleCountWorkExistsAtLocation(_location))
    {
        return false;
    }

    ttsbegin;

    if (avaisWorkTemplateBreakingWorkLines)
    {
        WHSWorkId cycleCountWorkId = dictClass_WhsCycleCountCreatePlan.callObject(identifierStr(createPartialCycleCountWorkHeader), this, _location);

        dictClass_WhsCycleCountCreatePlan.callObject(identifierStr(createCycleCountWorkWithMultipleWorkLines), this, cycleCountWorkId, _location, _itemAndDimensionsForWorkCreationSet);
    }
    else
    {
        WHSWorkId cycleCountWorkId = dictClass_WhsCycleCountCreatePlan.callObject(identifierStr(createFullCycleCountWorkHeader), this, _location);

        dictClass_WhsCycleCountCreatePlan.callObject(identifierStr(createCycleCountWorkLineForLocation), this, cycleCountWorkId, _location);
    }

    ttscommit;

    return true;
}
